        if abs(gx-blue[0])<blue_h[0]+0.22 and abs(gy-blue[1])<blue_h[1]+0.22:
            return 'SUCCESS',t
        if abs(gx-red[0])<red_h[0]+0.22 and abs(gy-red[1])<red_h[1]+0.22:
            return 'RED',t
    return 'TIMEOUT',len(obs)

