for k in [0,8,16,24,32,48,64]:
    a=[2]*k+[1]*128
    print('2x%d then 1:'%k, outcome(a))

# charge left, reverse, charge
for k in [8,16,24,32]:
    a=[1]*k+[2]*8+[1]*128
    print('1x%d 2x8 1:'%k, outcome(a))
